package org.sleepwell.app;
import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.provider.Settings;import android.Manifest;
final class PoseCameraAccess {static final int REQUEST=793;enum Status{READY,NEEDED,SETTINGS,UNSUPPORTED}static Status status(Activity a){if(!a.getPackageManager().hasSystemFeature(PackageManager.FEATURE_CAMERA_FRONT))return Status.UNSUPPORTED;if(a.checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)return Status.READY;return !Prefs.flag(a,"poseCameraAsked")||a.shouldShowRequestPermissionRationale(Manifest.permission.CAMERA)?Status.NEEDED:Status.SETTINGS;}static void request(Activity a){Status state=status(a);if(state==Status.UNSUPPORTED)throw new IllegalStateException("A front camera is required.");if(state==Status.READY)return;if(state==Status.SETTINGS){a.startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+a.getPackageName())));return;}Prefs.put(a,"poseCameraAsked",true);a.requestPermissions(new String[]{Manifest.permission.CAMERA},REQUEST);}private PoseCameraAccess(){}}
